from depth import *

Lecture('reliability-foundations',[
Q('object','Объект и требуемая функция','Надёжность оценивают у конкретного объекта относительно определённой функции. Начнём с границы: один сервер, канал связи и услуга обработки накладной — разные объекты.',[
 O(1),S('Компонент, система и услуга','Компонент может работать, а функция системы — не выполняться из-за другого обязательного звена. Для услуги «провести накладную» нужны допустимый запрос, обработка и сохранение результата. Критерий наблюдения задают на нужной границе.','Сервер без аппаратных отказов не доказывает надёжности всей услуги. И наоборот, отказ одного резервного узла может не нарушить услугу. В журнале различают событие компонента и нарушение функции системы.'),E('Один инцидент на двух уровнях','Учебная пара серверов обслуживает одну функцию; каждый способен нести полную нагрузку. Первый отключился, второй продолжил обслуживать запросы в заданных пределах. Зафиксирован отказ первого узла, но отказ услуги по этим наблюдениям не установлен.','Если переключение заняло больше допустимого перерыва, критерий услуги мог быть нарушен. Поэтому время переключения и предел должны быть в условии. Само наличие второго сервера не определяет результат.')],Check('Один резервируемый узел отказал, функция продолжилась в допустимых пределах. Что подтверждено?', ['Обязательно отказ всей услуги','Отказ компонента; отказ услуги не подтверждён','Отказа компонента не было'],1,'Уровни наблюдения различаются. Нужен критерий требуемой функции системы.'),'Надёжность связывают с объектом, функцией и наблюдаемым критерием.'),
Q('conditions','Условия и критерий работоспособности','Одинаковый симптом может иметь разный смысл при разных требованиях. До регистрации отказов фиксируют нагрузку, среду и допустимые пределы.',[
 S('Работоспособность и исправность','В учебном рассмотрении работоспособность означает выполнение требуемых функций с допустимыми параметрами. Исправность рассматривает соответствие установленным требованиям в целом. Незначительное внешнее повреждение и потеря основной функции не равноценны.','Не выводите состояние только из внешнего вида. Для информационной услуги нужны критерии: например, корректная запись и время ответа. Конкретный перечень требований устанавливается документацией, а не выбирается после удобного результата.'),S('Требование должно допускать проверку','«Работать быстро» не задаёт критерий. Учебное требование «сохранить допустимую накладную и ответить не позднее 2 с при 20 запросах/с» задаёт функцию, предел и условие нагрузки. Отдельно задают правило оценки серии измерений.','Один ответ 2,1 с может быть нарушением индивидуального предела, но для требования по p95 нужна выборка. Нельзя подменять один критерий другим в отчёте. Сначала читают точное условие, затем выбирают наблюдение.'),E('Ошибка пользователя и штатный отказ запроса','Сервис отклоняет накладную с отрицательным количеством, как и требует правило. Это отказ в выполнении недопустимого запроса, но не доказанный отказ работоспособности сервиса. Допустимый запрос проверяется отдельно.','Если система приняла недопустимую запись, возможен дефект проверки данных. Если отклоняет допустимые документы, нарушается требуемая функция. Одного слова Error в журнале для классификации недостаточно.')],Check('Система корректно отклонила запрещённое отрицательное количество. Это обязательно отказ ИС?', ['Да, всякий отказ запроса — отказ системы','Нет, это может быть штатное выполнение правила','Нужно удалить правило проверки'],1,'Классификация зависит от требуемого поведения: правильное отклонение недопустимого ввода сохраняет функцию.'),'Критерий отказа задают до наблюдения вместе с условиями нагрузки и работы.'),
Q('events','Отказ, сообщение и эпизод','Журнал сообщений не является готовым счётчиком отказов. Один непрерывный простой может породить десятки уведомлений.',[
 O(4),S('Начало и конец эпизода','Эпизод начинается при установленном нарушении критерия и заканчивается при подтверждённом восстановлении. Повторное уведомление внутри этого интервала не начинает новый эпизод без нового восстановления и последующего нарушения.','Для группировки нужны времена и объект. Совпадение текста сообщений недостаточно: два разных сервиса могут иметь одинаковую ошибку. В отчёте сохраняют правило объединения и исходные события.'),E('Три уведомления, один отказ','Учебная последовательность: 10:00 нарушение функции; 10:02 повтор; 10:05 повтор; 10:20 контрольная операция успешна. При непрерывном нарушении это один эпизод с восстановлением 20 минут.','Если в 10:10 была подтверждена работа, а в 10:12 критерий снова нарушился, появятся два эпизода. Изменилось не число строк, а история состояний.',table(['Время','Наблюдение','Учёт'],[['10:00','Первое нарушение','Начало эпизода'],['10:02 и 10:05','Повтор без восстановления','Тот же эпизод'],['10:20','Функция подтверждена','Конец эпизода']],'Количество уведомлений и количество отказов не совпадают автоматически.'))],Check('После первого нарушения пришли два повтора; до конца работоспособность не возвращалась. Сколько эпизодов?', ['1','2','3','Не менее 10'],0,'Без подтверждённого восстановления повторы относятся к одному непрерывному эпизоду при принятом критерии.'),'Отказы считают по эпизодам состояния, а не по строкам уведомлений.'),
Q('restoration','Восстановление и его состав','Возврат к работоспособности включает больше, чем ремонт устройства. Для услуги важны обнаружение, диагностика, действие и конечное подтверждение.',[
 S('Состав времени восстановления','Полный интервал от нарушения до восстановления может включать обнаружение, ожидание, диагностику, ремонт, запуск и проверку функции. Какие части входят в показатель, определяют до расчёта.','Если команда измеряет только активный ремонт, его среднее нельзя без оговорки назвать полным временем восстановления услуги. Сокращение ожидания специалиста может улучшить результат при неизменной длительности самого ремонта.'),S('Точка подтверждения восстановления','Служба запущена в 11:00, контрольная запись успешно проведена в 11:07. Если критерий относится к функции записи, окончание восстановления подтверждено в 11:07, а 11:00 — промежуточное событие.','Не удлиняйте эпизод произвольно после установленной проверки, но и не завершайте его раньше нужного свидетельства. Для каждого типа услуги заранее выбирают допустимую контрольную операцию.'),E('Ожидание влияет на итог','Учебный эпизод: обнаружение 5 мин, ожидание 25, действие 15, проверка 5. Полное восстановление — 50 мин; активное действие — 15. Сокращение ожидания до 5 даст 30 мин полного интервала.','Экономия 20 минут выведена из конкретной составляющей. Она не доказывает уменьшения частоты отказов. В отчёте сохраняют оба показателя и одинаковые границы сравнения.')],Check('Запуск занял 15 минут, весь интервал до подтверждения — 50. Что использовать для полного восстановления по условию?', ['15 минут','50 минут','Среднее 32,5 без основания'],1,'Нужен весь определённый условием интервал, а не только активное действие.'),'Границы времени восстановления и его составляющие определяют явно.'),
Q('journal','Журнал состояний и интервалы','Теперь построим источник для расчётов. События переводят в последовательные интервалы, не допуская пропусков и двойного учёта времени.',[
 O(3),S('Неперекрывающиеся состояния','Для выбранного фонда времени каждый момент относят к одному принятому состоянию: работа, восстановление, обслуживание или явно исключённый интервал. Сумма длительностей должна совпадать с фондом наблюдения.','При обслуживании внутри аварийного простоя нельзя складывать оба времени полностью. Нужен порядок классификации и исходные отметки. Иначе знаменатель станет длиннее реального периода.'),E('Перекрытие в журнале','Учебный простой 10:00–11:00; профилактика выполнена 10:20–10:40 внутри него. Объединённый нерабочий интервал длится 60 минут, а не 80. Для показателей виды времени распределяют по заранее принятому правилу.','Нельзя получить дополнительное календарное время суммированием пересечений. Сохраните оба события как сведения, но длительности состояний для одного фонда должны образовывать неперекрывающуюся разметку.')],Check('Простой 60 минут, внутри него 20 минут обслуживания. Какова длительность объединённого интервала?', ['20','60','80'],1,'Обслуживание целиком находится внутри простоя; длина объединения равна 60 минутам.'),'Журнал расчёта содержит согласованные состояния и проверенную сумму интервалов.'),
Q('exposure','Наработка и основания расчёта','Последний шаг подготовки — выбрать единицу работы и достаточные исходные сведения. Отсутствующие данные нельзя подменять нулём.',[
 O(2),O(5),S('Одинаковые правила наблюдения','Для сравнения периодов сохраняют объект, критерий отказа, нагрузку, правила учёта и полноту регистрации. Изменение мониторинга может увеличить число замеченных событий без ухудшения самого объекта.','Если раньше фиксировали только полную остановку, а теперь ещё превышение задержки, счётчики относятся к разным критериям. Нужно либо привести события к общему определению, либо явно разделить серии.'),E('Незавершённый эпизод','Наблюдение закончилось в 18:00, сервис ещё не восстановлен. Его полный интервал восстановления неизвестен; записывать нулевое время нельзя. Можно зафиксировать известную нижнюю границу длительности и статус незавершённости.','Среднее только по завершённым случаям имеет соответствующее ограничение. Скрытое исключение долгих незавершённых эпизодов способно сделать результат слишком благоприятным. Способ обработки таких данных должен быть указан отдельно.')],Check('К концу наблюдения восстановление не завершилось. Что записать?', ['0 минут','Незавершённый эпизод и известную часть интервала','Любое среднее других эпизодов'],1,'Полное время неизвестно. Ноль или подстановка другого значения выдумывают наблюдение.'),'Основание расчёта включает наработку, критерии, полноту и обработку незавершённых наблюдений.')
],[('Когда отказ компонента не является отказом услуги?','Когда оставшийся путь сохраняет требуемую функцию в установленных пределах.'),('Почему число сообщений об ошибке нельзя прямо подставлять как число отказов?','Нужны группировка по объекту и эпизоду, подтверждённые начала и восстановления.'),('Как неполный журнал может завысить оценку надёжности?','Пропущенные отказы или исключённые долгие незавершённые восстановления улучшают результат без изменения объекта.')],H('Период 09:00–13:00: работа до 10:00; нарушение в 10:00 и повтор в 10:05; восстановление подтверждено в 10:30; затем работа до 13:00.','Составьте неперекрывающийся журнал, посчитайте работу и восстановление, определите число эпизодов.','Сдайте таблицу интервалов и правило учёта повторного уведомления.','Работа 1+2,5=3,5 ч; восстановление 0,5 ч; фонд 4 ч; один эпизод.'))

Lecture('single-metrics',[
Q('probability','Вероятность безотказной работы','Начнём с вопроса о прохождении интервала без отказа. Он отличается от вопроса, работает ли объект после восстановления в конкретный момент.',[
 O(1),S('Горизонт и событие успеха','R(t) относится к заданной длительности t при определённых условиях и начальном работоспособном состоянии. Для более длинного горизонта событие «нет отказа на всём интервале» не становится вероятнее.','Число без горизонта неполно: R(1 ч) и R(100 ч) описывают разные события. Успешный ремонт после отказа не возвращает результат уже пройденного безотказного испытания: отказ в том интервале произошёл.'),E('Оценка по группе испытаний','Учебные 50 одинаково определённых независимых испытаний по 10 часов: 46 прошли без отказа, 4 — с отказом. Наблюдаемая доля безотказных испытаний 46/50=0,92 для этих условий и горизонта.','Не называйте 0,92 долей времени работы каждого объекта. Для вероятностного вывода есть неопределённость выборки; здесь рассчитывается простая наблюдаемая доля без доверительного интервала.')],Check('46 из 50 испытаний по 10 ч прошли без отказа. Какой показатель непосредственно оценён?', ['Наблюдаемая доля безотказных 10-часовых испытаний 0,92','92 часа восстановления','Годовая готовность любого сервера'],0,'Знаменатель — испытания с общим горизонтом, а не календарное время работы.'),'Вероятность безотказной работы всегда связывают с горизонтом и условиями.'),
Q('operating-mean','Средняя наработка на отказ','Теперь используем суммарную работу и число зарегистрированных отказов. Покажем, откуда берётся отношение и что в него не входит.',[
 O(2),S('Числитель и знаменатель оценки','В простой учебной оценке средняя наработка на отказ Tн = W/n, где W — суммарная наработка в часах, n — число отказов по одному критерию. Время простоя не включают в W, если W уже задано как работа.','Сначала проверьте, что W не является календарным фондом. Если в условии уже дана суммарная наработка, повторное вычитание восстановления ошибочно. При объединении объектов указывают, что считается объектом и как собрана экспозиция.'),E('Одинаковая календарная длительность','Два учебных объекта наблюдались по 100 часов. Первый работал 80 часов и имел 2 отказа; второй — 90 часов и 3 отказа. Оценки: 80/2=40 ч и 90/3=30 ч.','Деление 100 на число отказов смешало бы календарное время и наработку. Сравнение остаётся ограниченным малыми выборками и условиями нагрузки. Оно не устанавливает, что следующий отказ случится ровно через 40 или 30 часов.')],Check('Наработка уже задана как 1200 ч, отказов 6. Нужно ли ещё вычитать 12 ч восстановления?', ['Да, всегда','Нет: оценка 1200/6=200 ч','Нужно делить 12 на 6 вместо наработки'],1,'Числитель уже является временем работы. Повторное вычитание изменит его смысл.'),'Среднюю наработку оценивают по фактической работе и согласованному числу отказов.'),
Q('repair-mean','Среднее время восстановления','Для восстановления используется другая выборка: длительности эпизодов до подтверждённого возврата функции.',[
 S('Расчёт среднего восстановления','Для m завершённых эпизодов Tв = (r1+…+rm)/m. Каждая длительность имеет одинаковые границы начала и конца. Время активного ремонта и полный интервал восстановления нельзя смешивать в одной серии.','m может отличаться от числа начавшихся отказов, если часть эпизодов не завершена. Укажите это ограничение. Среднее только по коротким завершённым случаям может не представлять всю совокупность.'),E('Наблюдаемый пример восстановления','Учебные длительности: 30, 60 и 90 минут. Сумма 180 минут; среднее 60 минут, или 1 час. Максимальный эпизод 90 минут — отдельная характеристика, не равная среднему.','Если добавится завершённый эпизод 180 минут, среднее станет 360/4=90 минут. Изменение показывает чувствительность среднего к длинному восстановлению. Для эксплуатации полезно сохранять и исходный ряд.'),S('Незавершённое восстановление','Четвёртый эпизод длится уже 120 минут и продолжается. Нельзя добавить к среднему значение 0 или 120 как окончательное без оговорки. Фиксируют незавершённость и принятую методику анализа.','В простой учебной задаче можно отдельно посчитать среднее трёх завершённых эпизодов и описать ограничение. Такой результат не должен выдаваться за среднее всех четырёх фактических восстановлений.')],Check('Восстановления 30, 60 и 90 минут. Чему равно среднее в часах?', ['0,5','1','1,5','3'],1,'(30+60+90)/3=60 минут=1 час. Сначала суммируют одинаковые единицы.'),'Среднее восстановление считают по завершённым эпизодам с одинаковыми границами.'),
Q('rate','Интенсивность и частота событий','Свяжем число событий с объёмом наблюдения. Интерпретация отношения зависит от принятой модели, а не только от вычислителя.',[
 S('Оценка частоты наработки','В простой модели постоянной интенсивности оценка λ = n/W имеет размерность 1/ч при W в часах. Она показывает число событий на единицу суммарной работы в принятой модели. Это не вероятность, поэтому её не сравнивают с процентом без времени.','Для W=1200 ч и n=6 получаем 0,005 1/ч. Произведение λt безразмерно и используется в экспоненциальной модели. Само λ=0,005 не означает вероятность 0,5% для любого интервала.'),E('Число отказов и разная экспозиция','В периоде A зарегистрировано 4 отказа за 1000 ч работы, в B — 6 за 2000 ч. Оценки n/W: 0,004 и 0,003 1/ч. Абсолютное число выросло, но число на единицу работы уменьшилось.','Вывод требует одинаковых критериев, условий и полноты регистрации. Это пример нормирования, а не доказательство статистически значимого улучшения. При малых числах случайное различие может быть существенным.'),S('Нулевая выборка отказов','Если n=0, наблюдался период без зарегистрированных отказов. Отношение W/n не даёт конечную оценку средней наработки. Нельзя объявлять бесконечную надёжность или произвольно подставлять один отказ.','Сохраняют W, условия и факт нуля событий. Для вероятностной нижней границы нужны отдельная модель и уровень доверия; эта задача не решается одной заменой знаменателя.')],Check('A: 4 отказа/1000 ч; B: 6/2000 ч. Какой вывод по простому отношению верен?', ['В B частота выше, потому что 6 больше 4','В B отношение ниже: 0,003 против 0,004 1/ч','Показатели равны'],1,'Нужно нормировать на одинаковую единицу работы; абсолютные числа несопоставимы без экспозиции.'),'Частоту событий интерпретируют с единицей, экспозицией и ограничениями модели.'),
Q('exponential','Экспоненциальная модель','Теперь введём связь между средней наработкой и безотказным интервалом. Формула требует постоянной интенсивности и не назначается любой системе автоматически.',[
 O(3),S('Почему в показателе нет единицы','В R(t)=exp(−λt) время t и интенсивность λ используют согласованные единицы; λt безразмерно. При λ=1/Tн получаем R(t)=exp(−t/Tн). Знак минус делает вероятность убывающей при росте t.','Проверка крайних случаев: R(0)=1; при t>0 результат между 0 и 1; увеличение t уменьшает R. Если калькулятор дал больше единицы, проверьте знак. Если минуты подставлены к часовой λ, проверьте перевод.'),E('Один объект, разные горизонты','При Tн=200 ч: R(20)=exp(−0,1)≈0,9048; R(200)=exp(−1)≈0,3679. Средняя наработка 200 ч не означает гарантированную безотказную работу 200 часов.','Число 0,3679 показывает отличие среднего от жёсткого срока. В модели возможны и более ранние, и более поздние отказы. Средняя величина описывает распределение, а не расписание события.',table(['Горизонт','Показатель степени','R(t)'],[['0 ч','0','1'],['20 ч','−0,1','≈0,9048'],['200 ч','−1','≈0,3679']],'Постоянная интенсивность — принятое учебное допущение.'))],Check('При t=Tн в экспоненциальной модели чему равно R(t)?', ['1','0','exp(−1)≈0,3679','Tн часов'],2,'Отношение t/Tн=1, поэтому R=exp(−1). Среднее не является гарантированным сроком.'),'Экспоненциальную формулу применяют с постоянной интенсивностью и согласованными единицами.'),
Q('calculation','Полный порядок расчёта','Соберём исходные данные, оценки и модельный прогноз в одну последовательность, сохранив различие их смыслов.',[
 O(4),E('Перевод минут до подстановки','Учебная Tн=300 ч, горизонт 30 минут. t=0,5 ч; R=exp(−0,5/300)≈0,9983. Подстановка 30 вместо 0,5 дала бы exp(−0,1)≈0,9048 и другой горизонт.','Сначала запишите единицы рядом с каждым числом, затем сократите их в дроби. Ошибка возникает до вычислителя; дополнительное округление её не исправит.'),S('Точность и оформление','Вычисления проводят с достаточной промежуточной точностью; округляют итог до заданного разряда. В ответе указывают исходные W, n, времена восстановления, горизонт и принятое допущение.','Одинаковое число знаков не делает разные показатели сопоставимыми. Подпись «R(30 мин)≈0,9983 при постоянной λ» полезнее, чем отдельное 99,83%. Процент переводится умножением на 100, а время сохраняет единицу.')],Check('Tн=300 ч, горизонт 30 минут. Какой показатель степени верен?', ['−30/300','−0,5/300','−300/30'],1,'30 минут = 0,5 часа. Единицы числителя и знаменателя должны совпадать.'),'Расчёт оформляют как переход от исходных данных через единицы и модель к подписанному результату.'),
Q('limits','Проверка смысла и границ','В заключение отделим результат арифметики от силы вывода. Правильная формула не компенсирует несогласованные исходные события.',[
 O(5),S('Изменение режима работы','Рост нагрузки, новая версия, изменение критерия отказа или состава объекта могут сделать серии неоднородными. Перед сравнением показателей проверяют, сохраняются ли условия и метод наблюдения.','Например, после включения нового мониторинга стало больше зарегистрированных коротких эпизодов. Это не автоматически ухудшение оборудования. Сначала определяют, какие события раньше не наблюдались.'),E('Откуда не следует готовность','Система имеет Tн=200 ч, но длительности восстановления не заданы. Можно сделать модельный расчёт R(t) при принятых допущениях, однако коэффициент готовности по Tн/(Tн+Tв) вычислить нельзя.','Недостающий Tв не равен нулю. Запишите, какие данные нужно собрать. Этот пример показывает, почему близкие слова «надёжность» и «доступность» не разрешают подставлять один показатель вместо другого.')],Check('Известна средняя наработка, время восстановления неизвестно. Можно ли вычислить Kг по двухсостоянийной формуле?', ['Да, положив Tв=0','Нет, требуется Tв и применимость модели','Да, Kг всегда равно R(1)'],1,'Формула требует отдельного параметра восстановления. Его нельзя выдумывать.'),'Итоговый показатель сохраняет смысл исходной выборки и принятых допущений.')
],[('Чем R(20 ч) отличается от среднего времени до отказа?','Первое — вероятность пройти горизонт без отказа; второе — средняя длительность с единицей времени.'),('Почему ноль отказов не даёт бесконечной доказанной надёжности?','Наблюдение ограничено наработкой и условиями; простая оценка W/n не определена.'),('Какие проверки выполняют до exp(−t/Tн)?','Применимость постоянной интенсивности, единицы времени, знак и заданный горизонт.')],H('Суммарная наработка 2400 ч, зарегистрировано 8 отказов; завершённые восстановления в сумме 16 ч. Для экспоненциального учебного расчёта горизонт 24 ч.','Рассчитайте Tн, Tв и R(24); подпишите единицы и допущение.','Сдайте три отдельных расчёта и объясните, почему это разные показатели.','Tн=300 ч; Tв=2 ч; R(24)=exp(−0,08)≈0,9231. Приняты постоянная интенсивность и сопоставимые события.'))

Lecture('availability',[
Q('readiness','Готовность восстанавливаемой системы','Готовность учитывает возвращение к работе после отказа. Начнём с простой модели и отделим её параметр от результата конкретного журнала.',[
 O(1),S('Два состояния и длительный режим','В простой модели объект чередует работоспособное состояние и восстановление. При применимости модели Kг=Tн/(Tн+Tв) характеризует стационарную долю готовности. Короткий конечный журнал может дать другое наблюдаемое отношение.','Формула не описывает автоматически плановые выключения и все организационные ожидания. Сначала указывают, что включено в Tв и как определена работа. Термин «стационарный» означает установившийся режим модели, а не неизменность любого реального дня.'),E('Одинаковая наработка, разное восстановление','Учебные системы A и B имеют Tн=100 ч. У A Tв=1 ч: Kг=100/101≈0,9901. У B Tв=10 ч: Kг=100/110≈0,9091. Частота отказов в модели одинакова, готовность различается.','Разница возникает из длительности возврата, а не из дополнительной безотказности. Для непрерывной операции даже короткий перерыв может оставаться неприемлемым при высоком Kг.')],Check('При одинаковой Tн сокращение Tв в этой модели приводит к чему?', ['Kг увеличивается','Число отказов обязательно становится нулевым','R(t) автоматически становится 1'],0,'Меняется доля готовности; частота отказов и вероятность безотказного интервала не изменяются только из-за Tв.'),'Готовность учитывает длительность восстановления и отличается от безотказности.'),
Q('utilization','Техническое использование','Добавим плановое обслуживание и полный принятый фонд. Новый знаменатель отвечает на другой эксплуатационный вопрос.',[
 O(2),S('Роль планового обслуживания','В учебном фонде время обслуживания выделяется отдельно от работы и восстановления. Для Kти используют долю работы во всём заданном неперекрывающемся фонде. Исключения, например нерабочие смены, должны быть названы.','Обслуживание может снижать будущую аварийность, но в текущем фонде занимает время. Поэтому рост профилактики не следует автоматически называть ухудшением или улучшением всей системы: нужно оценить последствия и принятые требования.'),E('Изменение классификации без изменения работы','Учебная работа — 900 ч, восстановление — 20, обслуживание — 80. Если обслуживание скрыто исключить, получится 900/920≈0,9783 вместо Kти=900/1000=0,9.','Это изменение знаменателя, а не улучшение объекта. Для сравнения периодов сохраняют одно определение фонда. Формально правильные дроби могут отвечать на разные вопросы.')],Check('900 ч работы, 20 восстановления, 80 обслуживания. Каков Kти полного фонда?', ['0,9','0,9783','0,02','1,08'],0,'Полный фонд 1000 ч, доля работы 900/1000=0,9.'),'Техническое использование связывает работу с явно заданным полным фондом.'),
Q('fund','Подготовка фонда времени','Числитель и знаменатель формируются из журнала. Проверим сумму, пересечения и исключённые периоды до вычисления дроби.',[
 O(3),S('Баланс времени','Для каждого интервала определяют начало, конец и состояние. Проверяют, что интервалы не пересекаются и покрывают выбранный период. Неизвестное время фиксируют отдельно; его нельзя молча считать работой.','Баланс — арифметическая и смысловая проверка. Если суммы не совпали, показатель ещё не готов к интерпретации. Уточняют записи, а не подгоняют остаток под удобный процент.'),E('Обнаруженный пробел','Учебный фонд — 1000 ч; работа 850, восстановление 30, обслуживание 70. Сумма 950 ч; 50 ч не классифицированы. Доля 850/1000=0,85 вычислима, но её смысл зависит от судьбы неизвестных 50 ч.','Нельзя объявлять 850/950 техническим использованием полного фонда. Нужно уточнить интервалы или явно представить ограниченный результат с неизвестной частью. Два разных знаменателя не взаимозаменяемы.')],Check('В полном фонде 1000 ч классифицированы только 950. Что делать прежде окончательного Kти?', ['Оставшиеся 50 считать работой без проверки','Уточнить или явно обозначить неизвестный интервал','Уменьшить фонд без основания'],1,'Неизвестное время является пробелом данных; оно не должно незаметно менять определение показателя.'),'Баланс фонда проверяют до расчёта и не заменяют неизвестные интервалы удобным состоянием.'),
Q('effect','Изменение показателя и его причина','Посмотрим, какие параметры меняют результат. Одинаковый коэффициент может скрывать разную частоту и длительность остановок.',[
 O(4),S('Один коэффициент — разные режимы','Учебные пары Tн=100, Tв=1 и Tн=1000, Tв=10 дают одинаковое отношение 100/101≈0,9901. Вторая система в модели реже отказывает, но дольше восстанавливается.','Для пользователя с допустимым перерывом 2 часа второй режим может нарушать требование к каждой остановке. Поэтому коэффициент дополняют ограничениями на длительность и последствия отказа.'),E('Цена более долгой профилактики','Учебный фонд 1000 ч: сначала работа 900, восстановление 60, обслуживание 40; затем работа 930, восстановление 10, обслуживание 60. Kти вырос с 0,90 до 0,93 при увеличении обслуживания.','Профилактика добавила 20 ч, но аварийный простой сократился на 50 ч, что освободило 30 ч работы. Пример показывает баланс последствий; он не доказывает, что любая дополнительная профилактика даёт такой эффект.')],Check('Одинаковый Kг у двух систем означает одинаковую максимальную остановку?', ['Да','Нет: частота и длительность могут различаться','Только если одинаковы названия'],1,'Отношение двух параметров не определяет каждый параметр и максимум эпизодов.'),'Эффект меры объясняют изменением конкретных времён и последствий, а не одним коэффициентом.'),
Q('comparison','Проценты и процентные пункты','Сравнение требует одинакового фонда и правильного языка. Разность долей, процентные пункты и относительное изменение — разные величины.',[
 S('Три формы изменения','Рост доли с 0,90 до 0,95 равен 0,05 доли, или 5 процентным пунктам. Относительный рост к исходному уровню равен 0,05/0,90≈5,56%. Основание относительного сравнения указывают явно.','Снижение доли простоя с 0,10 до 0,05 составит 50% относительно прежнего простоя. Это не противоречит 5 п.п. роста работы: сравниваются разные основания.'),E('Время за процентом','Учебный фонд 2000 ч; рост использования с 0,96 до 0,98 при неизменном фонде соответствует 0,02×2000=40 дополнительным часам работы.','Если фонды различаются, разность коэффициентов нельзя прямо умножить на любой из них как фактический прирост. Нужно отдельно вычислить рабочее время каждого периода.',table(['Форма','Вычисление','Результат'],[['Разность долей','0,98−0,96','0,02'],['Процентные пункты','98−96','2 п.п.'],['Дополнительная работа','0,02×2000 ч','40 ч']],'Перевод в часы верен при одинаковом фонде 2000 часов.')),
 S('Договорный показатель и учебная модель','Правила договорной доступности могут определять свои окна, исключения, способы измерения и события. Учебный Kг или Kти не объявляют автоматически выполнением любого договорного требования.','Для реального сравнения сначала читают определение показателя в применимом документе. Нужны источник данных и одинаковое правило учёта. Сходство названия не гарантирует одинакового знаменателя.')],Check('Доля выросла с 0,96 до 0,98. Какова разность в процентных пунктах?', ['0,02 п.п.','2 п.п.','20 п.п.','98 п.п.'],1,'96%→98% даёт 2 процентных пункта; разность долей равна 0,02.'),'Сравнение сохраняет определение показателя, фонд и основание изменения.'),
Q('procedure','Порядок расчёта и проверка','Завершим целой процедурой: данные → баланс → показатель → интерпретация → обоснованная мера.',[
 O(5),E('Проверка допустимых границ','При положительных неперекрывающихся временах учебные Kг и Kти находятся от 0 до 1. Для одного фонда с дополнительным обслуживанием Kти не превышает долю работы без обслуживания.','Если значение вышло за единицу, ищите повтор времени, неверный числитель или перепутанные единицы. Нулевая наработка также требует анализа смысла: формально полученное число без функции работы не описывает обычный режим эксплуатации.'),S('Как оформить вывод','В выводе называют показатель, период, объект, исходные длительности, исключения и ограничение. Предлагаемая мера должна воздействовать на выявленную составляющую: ожидание, ремонт, обслуживание или частоту событий.','Не обещайте удвоение надёжности по росту Kг на несколько тысячных. Покажите, какое требование стало выполняться и какие сценарии нужно проверить после изменения. Расчёт обосновывает гипотезу меры, а испытание подтверждает реализацию.')],Check('Kти получился 1,08 при заявленном полном фонде. Что обосновано?', ['Принять 108% работы как отличный результат','Проверить исходные интервалы, единицы и состав числителя','Округлить до 1 без объяснения'],1,'Доля работы в её полном неперекрывающемся фонде не может превышать единицу.'),'Расчёт заканчивается проверкой границ и выводом по конкретному требованию.')
],[('Почему Kг и Kти могут различаться по одному журналу?','У них разные принятые знаменатели, в частности учёт обслуживания.'),('Как две системы с одинаковым Kг могут по-разному влиять на процесс?','У них могут различаться частота, длительность и максимум перерывов.'),('Чем 2 п.п. отличаются от роста на 2%?','Пункты — разность процентов; относительные проценты требуют деления на исходный уровень.')],H('Фонд 1000 ч: работа 840, восстановление 35, обслуживание 125. Затем 50 ч обслуживания заменены работой, остальные значения прежние.','Рассчитайте Kти до и после; отдельно найдите наблюдаемую долю работы без обслуживания для исходного периода.','Сдайте два определения знаменателя и изменение в процентных пунктах.','Kти: 0,84→0,89, рост 5 п.п.; исходная доля без обслуживания 840/875=0,96.'))

Lecture('system-reliability',[
Q('success','Условие успеха и структурная модель','Формула следует из логики функции. Начнём с того, какие элементы обязательны и какие могут заменять друг друга.',[
 S('Физическая схема и логика надёжности','Физическая звезда сети может соответствовать последовательной логике услуги: нужны АРМ, коммутатор и сервер. Параллельность в модели означает, что для требуемой функции достаточно работающего альтернативного пути.','Рисуйте условие словами до формул: «нужны все» или «достаточно хотя бы одного». Две нарисованные рядом коробки ещё не образуют резерв. Нужно проверить функцию, нагрузку и разрешённое переключение.'),S('Общий горизонт и событие','Все Ri(t) должны относиться к одному горизонту и согласованному событию успеха. Нельзя перемножить вероятность безотказной работы за час и готовность за год, будто это показатели одного вида.','Готовность и безотказность могут иметь похожие структурные выражения в специальных моделях, но здесь считаем только заданные вероятности прохождения общего горизонта. Восстановление внутри него этой простой моделью не описывается.'),E('Одна пара — два условия','Два независимых модуля имеют R=0,9. Если нужны оба, успех равен 0,81. Если достаточно любого при полной нагрузочной способности, успех равен 0,99. Разница определяется условием функции.','Не выбирайте более удобную формулу по желаемому большему результату. Изменение логики означает изменение конструкции или требований, а не новый способ округления.')],Check('Когда применима простая параллельная модель двух каналов?', ['Любые два корпуса стоят рядом','Достаточно хотя бы одного, каждый выполняет функцию и приняты условия независимости и переключения','Нужны оба одновременно'],1,'Параллельность задаётся условием успеха и допущениями, а не геометрией рисунка.'),'Структурную модель выбирают после функции, общего горизонта и логики успеха.'),
Q('series','Последовательное условие','Когда нужны все независимые элементы, отказ любого обязательного элемента нарушает функцию. Выведем произведение и проверим его границы.',[
 O(1),E('Три обязательных элемента','Учебные вероятности на одном горизонте: АРМ 0,99; сеть 0,98; сервер 0,97. При независимости успех всех: 0,99×0,98×0,97=0,941094.','Результат ниже каждой из трёх вероятностей, что согласуется с обязательностью всех элементов. Среднее арифметическое здесь не описывает вероятность совместного успеха.'),S('Добавление обязательного звена','Если к обязательной цепи добавить элемент с R<1, произведение уменьшается. Это не означает, что дополнительные функции всегда вредны: меняется сама рассматриваемая услуга и её необходимые условия.','В проектном выводе различают улучшение компонента и расширение состава функции. Сравнение старой и новой цепи допустимо только при ясно указанной цели. Идеальный элемент R=1 не меняет произведение.')],Check('Для обязательных независимых элементов R1=0,9 и R2=0,8 каков результат?', ['0,72','0,98','0,85','1,7'],0,'Нужны оба: 0,9×0,8=0,72. Среднее не является совместной вероятностью.'),'Для обязательных независимых элементов используется произведение, не превышающее слабейший элемент.'),
Q('parallel','Параллельное резервирование','Для альтернативных путей удобнее посчитать противоположное событие — отказ всех доступных вариантов.',[
 O(2),E('Неодинаковые резервные каналы','Учебные каналы: R1=0,9 и R2=0,8 на одном горизонте. Независимость, идеальное переключение и полная нагрузочная способность заданы. Совместный отказ: 0,1×0,2=0,02; успех: 0,98.','Надёжности каналов не обязаны совпадать. Результат не ниже каждого канала в этой идеальной модели. Если требуется одновременная работа обоих, это уже другая логика и результат 0,72.'),S('Резерв должен выполнять всю функцию','Если каждый канал способен передать только половину обязательной нагрузки, потеря одного нарушит требование полной производительности. Наличие двух путей само по себе не выполняет условие «достаточно любого».','Перед расчётом проверяют пропускную способность оставшегося пути и допустимое время перехода. То, что резервный интерфейс включён, не является испытанием всего сценария.')],Check('Каждый из двух путей выдерживает только половину требуемой нагрузки. Можно ли без оговорки считать успех по «достаточно любого»?', ['Да','Нет, одиночный путь не выполняет заданную функцию','Да, если одинаковые названия'],1,'Параллельная модель требует, чтобы оставшийся путь обеспечивал нужную функцию в заданных пределах.'),'Идеальный резерв считают через отказ всех каналов, предварительно подтвердив их достаточность.'),
Q('mixed','Последовательно-параллельная структура','Реальная функция часто содержит резервируемую группу и общие обязательные элементы. Рассчитаем её по частям.',[
 O(3),E('Три шага смешанной модели','Учебный сервер R=0,96; два независимых альтернативных канала по 0,9; общий коммутатор R=0,98 независим от группы и сервера. Сеть: 0,99; с коммутатором: 0,9702; вся функция: 0,931392.','Сначала сворачивают внутреннюю резервную группу, затем последовательно включают обязательные элементы. Итог ниже 0,96, потому что сервер обязателен. Потеря множителя коммутатора дала бы необоснованно высокий результат.',table(['Этап','Выражение','Результат'],[['Пара каналов','1−0,1²','0,99'],['С общим коммутатором','0,99×0,98','0,9702'],['С сервером','0,9702×0,96','0,931392']],'Все величины относятся к одному горизонту; общие элементы вынесены явно.')),
 S('Проверка результата по структуре','Для смешанной структуры итог не выше надёжности каждого обязательного общего элемента. Резервная группа не устраняет ограничение общего сервера, питания или маршрута.','Это быстрая проверка ошибки, но не замена вывода формулы. Если после резервирования сети получилось больше вероятности обязательного сервера, нужно проверить выражение и границу объекта.')],Check('В смешанной модели сервер R=0,96 обязателен. Итог 0,995 при остальных элементах неидеальных выглядит как что?', ['Ожидаемый успех резерва','Основание проверить модель: итог не может превышать обязательный сервер','Доказательство идеального переключения'],1,'При необходимости сервера общий успех является подмножеством события его работы.'),'Смешанную структуру рассчитывают от внутренних групп к общим обязательным элементам.'),
Q('dependence','Зависимости и общая причина','Произведения требуют соответствующих условий независимости. Выделим общие элементы и покажем, почему два пути могут отказывать вместе.',[
 O(4),S('Общее питание и общая конфигурация','Каналы могут зависеть от одного питания, трассы, коммутатора, поставщика или ошибочной общей настройки. Независимость отказов нельзя вывести только из разных номеров устройств.','Общий обязательный элемент можно показать отдельным блоком, если его событие и связь с группой определены. Сложные зависимости требуют иной модели; не придумывайте коэффициент корреляции без данных.'),E('Почему второй кабель может не помочь','Учебные два кабеля идут через один коммутатор и одну кабельную трассу. Для обрыва отдельного кабеля есть альтернативный путь, для отказа общего коммутатора или трассы — нет.','Эффект резерва относится к конкретной причине. Схема проверки должна включать разрешённый отказ одного пути и отдельно анализ общего элемента. Нельзя записывать успешный тест кабеля как проверку независимости всей инфраструктуры.')],Check('Два канала используют один общий коммутатор. Как учесть его?', ['Считать каналы полностью независимыми от любого общего элемента','Выделить обязательную общую зависимость и задать её роль в модели','Удвоить R каждого канала'],1,'При отказе коммутатора оба пути могут исчезнуть. Общая зависимость должна присутствовать в условии успеха.'),'Резервирование оценивают по конкретным причинам отказа и общим зависимостям.'),
Q('decision','Эффект резерва и эксплуатационная проверка','Завершим сравнением вариантов. Расчёт объясняет ожидаемый эффект, а испытание проверяет реализацию переключения и возврата.',[
 O(5),S('Абсолютный эффект и ограничения','Для вероятности 0,90→0,99 разность составляет 0,09, или 9 процентных пунктов. Относительное уменьшение вероятности отказа 0,10→0,01 равно 90%. Это разные формы описания одного модельного перехода.','Не называйте такой расчёт гарантией годовой доступности. Он относится к заданному горизонту и условиям. Выбор также зависит от нагрузки, стоимости и допустимого времени перерыва.'),E('Что проверяют у установленного резерва','На разрешённом стенде фиксируют исходную функцию, выводят один путь, измеряют переключение, проверяют операцию на оставшемся пути и возвращают исходную конфигурацию. Затем повторяют для другого пути.','Нужны оба направления и возврат. Если испытан только первый кабель, второй отказный сценарий остаётся непроверенным. Сохранение данных после перехода проверяют той же предметной операцией, для которой строилась модель.')],Check('Установлены два пути, испытан отказ только первого. Что можно утверждать?', ['Проверены все сценарии резерва','Проверен один сценарий; второй и возврат требуют отдельного подтверждения','Расчёт заменил все испытания'],1,'Покрытие вывода ограничено фактически выполненными сценариями.'),'Эффект резерва подписывают по модели и подтверждают отдельным испытанием каждого пути и возврата.')
],[('Почему физическая звезда может иметь последовательную модель надёжности?','Функция требует одновременно АРМ, коммутатор и сервер: отказ обязательного элемента прерывает её.'),('Какие допущения нужны для простой параллельной формулы?','Независимость, общий горизонт, достаточность каждого пути и идеальное разрешённое переключение.'),('Что ограничивает эффект резервирования только сети?','Общие обязательные серверы, питание, устройства и другие неизменённые причины отказа.')],H('Два независимых альтернативных канала имеют R=0,92 каждый, сервер — обязательный R=0,97. На том же горизонте переключение идеально, каждый канал держит полную нагрузку.','Посчитайте вариант с одним каналом и с двумя; затем добавьте общий независимый коммутатор R=0,96.','Сдайте структурную схему, промежуточные результаты и изменение в процентных пунктах до общего коммутатора.','Один: 0,8924; группа: 0,9936; с сервером: 0,963792; прирост 7,1392 п.п.; с коммутатором: 0,92524032.'))
